    Bug 1223951 - Do not duplicate correspondents when re-indexing a gloda message. r=mkmelin


    This happens when the junk status of a messages changes, or a folder is being reindexed via "Repair Folder".

    Differential Revision: https://phabricator.services.mozilla.com/D250784

diff --git a/mailnews/db/gloda/modules/GlodaFundAttr.sys.mjs b/mailnews/db/gloda/modules/GlodaFundAttr.sys.mjs
index 011f93e7768..cdcf412107c 100644
--- a/mailnews/db/gloda/modules/GlodaFundAttr.sys.mjs
+++ b/mailnews/db/gloda/modules/GlodaFundAttr.sys.mjs
@@ -623,12 +623,12 @@ export var GlodaFundAttr = {

     // for simplicity this is used for both involves and recipients
     const involvesIdentities = {};
-    const involves = aGlodaMessage.involves || [];
-    const recipients = aGlodaMessage.recipients || [];
+    const involves = [];
+    const recipients = [];

     // 'me' specialization optimizations
-    const toMe = aGlodaMessage.toMe || [];
-    const fromMe = aGlodaMessage.fromMe || [];
+    const toMe = [];
+    const fromMe = [];

     const myIdentities = Gloda.myIdentities; // needless optimization?
     const authorIdentity = aGlodaMessage.from;
diff --git a/mailnews/db/gloda/test/unit/base_index_junk.js b/mailnews/db/gloda/test/unit/base_index_junk.js
index fab72ae6b39..a001ba5329a 100644
--- a/mailnews/db/gloda/test/unit/base_index_junk.js
+++ b/mailnews/db/gloda/test/unit/base_index_junk.js
@@ -126,13 +126,25 @@ function reset_spam_filter() {
  */

 async function test_mark_as_junk_is_deletion_mark_as_not_junk_is_exposure() {
+  // Test that reindexing a message does not duplicate the existing identities
+  // of the gloda message.
+  const verifyIdentities = (_, gmsg) => {
+    Assert.equal(gmsg.involves.length, 2);
+    Assert.equal(gmsg.recipients.length, 1);
+  };
+
   // Mark as junk is deletion.
   // Create a message; it should get indexed.
   const [, msgSet] = await messageInjection.makeFoldersWithSets(1, [
     { count: 1 },
   ]);
   await waitForGlodaIndexer();
-  Assert.ok(...assertExpectedMessagesIndexed([msgSet], { augment: true }));
+  Assert.ok(
+    ...assertExpectedMessagesIndexed([msgSet], {
+      augment: true,
+      verifier: verifyIdentities,
+    })
+  );
   const glodaId = msgSet.glodaMessages[0].id;
   // Mark it as junk.
   msgSet.setJunk(true);
@@ -142,7 +154,12 @@ async function test_mark_as_junk_is_deletion_mark_as_not_junk_is_exposure() {
   // Mark as non-junk gets indexed.
   msgSet.setJunk(false);
   await waitForGlodaIndexer();
-  Assert.ok(...assertExpectedMessagesIndexed([msgSet], { augment: true }));
+  Assert.ok(
+    ...assertExpectedMessagesIndexed([msgSet], {
+      augment: true,
+      verifier: verifyIdentities,
+    })
+  );
   // We should have reused the existing gloda message so it should keep the id.
   Assert.equal(glodaId, msgSet.glodaMessages[0].id);
 }
